WITH RECURSIVE ancestors AS (
    SELECT id,parent_id FROM comments WHERE id=#{commentId} AND post_id=#{postId}
    UNION ALL
    SELECT c.id,c.parent_id FROM comments c JOIN ancestors a ON a.parent_id=c.id
    WHERE c.post_id=#{postId}
) SELECT id FROM ancestors WHERE parent_id IS NULL

mapper.sql:
WITH RECURSIVE thread_ids AS (
    SELECT id FROM comments WHERE id=#{rootCommentId} AND post_id=#{postId}
    UNION ALL
    SELECT c.id FROM comments c JOIN thread_ids t ON c.parent_id=t.id
    WHERE c.post_id=#{postId}
)

mapper.select:
, recent AS (
    SELECT c.id FROM comments c JOIN thread_ids t ON t.id=c.id
    ORDER BY c.created_at DESC,c.id DESC LIMIT #{limit}
)

JOIN recent r ON r.id=c.id
ORDER BY c.created_at,c.id

