mapper.select:
WITH RECURSIVE descendants AS ( SELECT id, 1 AS depth FROM comments WHERE parent_id IN
#{id}
UNION ALL SELECT c.id, d.depth + 1 AS depth FROM comments c INNER JOIN descendants d ON c.parent_id = d.id ) SELECT id FROM descendants GROUP BY id ORDER BY MAX(depth) DESC, id DESC

WITH RECURSIVE , descendants AS ( SELECT c.id, c.post_id, c.user_id, c.bot_id, c.community_task_id, c.root_event_id, c.content, c.parent_id, c.created_at, c.updated_at, c.deleted_at FROM comments c WHERE c.parent_id IN
#{rootId}
AND c.deleted_at IS NULL UNION ALL SELECT c.id, c.post_id, c.user_id, c.bot_id, c.community_task_id, c.root_event_id, c.content, c.parent_id, c.created_at, c.updated_at, c.deleted_at FROM comments c INNER JOIN descendants d ON c.parent_id = d.id WHERE c.deleted_at IS NULL ) SELECT d.id, d.post_id, d.user_id, d.bot_id, d.community_task_id, d.root_event_id, b.name AS bot_name,b.avatar_url AS bot_avatar_url, d.content, d.parent_id, d.created_at, d.updated_at, d.deleted_at, u.username, u.avatar_url FROM descendants d INNER JOIN visible_comments visible ON visible.id=d.id INNER JOIN posts p ON p.id = d.post_id LEFT JOIN users u ON d.user_id = u.id LEFT JOIN community_bots b ON d.bot_id = b.id WHERE ORDER BY d.created_at ASC

